{"content":"package config

import (
	"testing"
	"time"
)

func env(m map[string]string) func(string) string { return func(k string) string { return m[k] } }

func TestLoadDefaults(t *testing.T) {
	c, err := Load(env(nil))
	if err != nil || c.Host != "localhost" || c.Port != 8080 || c.Workers != 4 ||
		c.Timeout != 30*time.Second || c.Tags != nil {
		t.Fatalf("%+v %v", c, err)
	}
}

func TestLoadOverrides(t *testing.T) {
	c, err := Load(env(map[string]string{"APP_PORT": "9000", "APP_DEBUG": "true"}))
	if err != nil || c.Port != 9000 || !c.Debug {
		t.Fatalf("%+v %v", c, err)
	}
}

func TestLoadTimeout(t *testing.T) {
	c, err := Load(env(map[string]string{"APP_TIMEOUT": "1m5s"}))
	if err != nil || c.Timeout != 65*time.Second {
		t.Fatalf("%+v %v", c, err)
	}
}

func TestLoadTags(t *testing.T) {
	c, err := Load(env(map[string]string{"APP_TAGS": " a, b ,,c "}))
	if err != nil {
		t.Fatal(err)
	}
	want := []string{"a", "b", "c"}
	if len(c.Tags) != len(want) {
		t.Fatalf("tags = %v, want %v", c.Tags, want)
	}
	for i := range want {
		if c.Tags[i] != want[i] {
			t.Fatalf("tags = %v, want %v", c.Tags, want)
		}
	}
}

func TestLoadTagsAllEmpty(t *testing.T) {
	c, err := Load(env(map[string]string{"APP_TAGS": " , ,"}))
	if err != nil || c.Tags != nil {
		t.Fatalf("%+v %v", c, err)
	}
}

func TestLoadCollectsAllErrors(t *testing.T) {
	c, err := Load(env(map[string]string{
		"APP_PORT":    "99999",
		"APP_DEBUG":   "nope",
		"APP_WORKERS": "0",
		"APP_TIMEOUT": "soon",
	}))
	if err == nil {
		t.Fatal("expected error")
	}
	for _, name := range []string{"APP_PORT", "APP_DEBUG", "APP_WORKERS", "APP_TIMEOUT"} {
		if !contains(err.Error(), name) {
			t.Errorf("error %q does not mention %s", err, name)
		}
	}
	if c != (Config{}) {
		t.Fatalf("expected zero Config, got %+v", c)
	}
}

func contains(s, sub string) bool {
	for i := 0; i+len(sub) <= len(s); i++ {
		if s[i:i+len(sub)] == sub {
			return true
		}
	}
	return false
}

func TestMergeOverrideWins(t *testing.T) {
	base := Defaults()
	ov := Config{Host: "example.com", Port: 9090, Workers: 8, Timeout: 5 * time.Second, Tags: []string{"x"}}
	c := Merge(base, ov)
	if c.Host != "example.com" || c.Port != 9090 || c.Workers != 8 ||
		c.Timeout != 5*time.Second || len(c.Tags) != 1 || c.Tags[0] != "x" {
		t.Fatalf("%+v", c)
	}
}

func TestMergeKeepsBaseForZeroOverride(t *testing.T) {
	base := Defaults()
	c := Merge(base, Config{})
	if c != base {
		t.Fatalf("got %+v, want %+v", c, base)
	}
}

func TestMergeEmptyTagsReplace(t *testing.T) {
	base := Config{Tags: []string{"a", "b"}}
	c := Merge(base, Config{Tags: []string{}})
	if c.Tags == nil || len(c.Tags) != 0 {
		t.Fatalf("tags = %#v, want empty non-nil", c.Tags)
	}
}

func TestMergeNilTagsKeepsBase(t *testing.T) {
	base := Config{Tags: []string{"a", "b"}}
	c := Merge(base, Config{})
	if len(c.Tags) != 2 || c.Tags[0] != "a" {
		t.Fatalf("tags = %v", c.Tags)
	}
}

func TestMergeDoesNotMutateArguments(t *testing.T) {
	base := Config{Tags: []string{"a", "b"}}
	ov := Config{Tags: []string{"c"}}
	c := Merge(base, ov)
	if len(base.Tags) != 2 || base.Tags[0] != "a" || base.Tags[1] != "b" {
		t.Fatalf("base mutated: %v", base.Tags)
	}
	if len(ov.Tags) != 1 || ov.Tags[0] != "c" {
		t.Fatalf("override mutated: %v", ov.Tags)
	}
	if c == (Config{}) {
		t.Fatal("unexpected zero result")
	}
}
